def keep_private(path: str, *, folder: bool = True, create: bool = True) -> bool:
    """*path* readable by this user alone, and with *folder* the folder it is
    in too (made at 0700 when missing). *create*: a missing file made empty
    at 0600 first. Never raises; False when it could not be done - logged
    with the file's name and kept in not_private()."""
    if os.name != "posix" or not path:
        return True
    try:
        kept = True
        if folder:
            parent = os.path.dirname(path)
            os.makedirs(parent, mode=FOLDER_MODE, exist_ok=True)
            if not _theirs(parent):
                _note(path, "its folder is another account's")
                return False
            kept = _narrow(parent, FOLDER_MODE)
        if os.path.islink(path) and not os.path.exists(path):
            # A link to nothing: what is written there lands where it
            # points, which nothing here has made private.
            _note(path, "a link to a file that is not there")
            return False
        if create and not os.path.lexists(path):
            try:
                os.close(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, FILE_MODE))
            except FileExistsError:
                pass
        if os.path.exists(path):
            if not _theirs(path):
                _note(path, "another account owns it")
                return False
            kept = _narrow(path, FILE_MODE) and kept
        if not kept:
            _note(path, "its drive keeps no permissions")
        return kept
    except OSError as e:
        _note(path, e.strerror or type(e).__name__)
        return False

def redact_text(text: str) -> str:
    """*text* the app did not write - a line ffmpeg or mpv printed, an
    exception's message - safe to log: every address in it masked
    (_address_masked), a query or an Xtream account without its address,
    a login header, a bearer token, a login written name=value and a box's
    MAC, then every registered value. Never raises - and fails closed: a
    fault in any step gives WITHHELD, never the text half-masked."""
    try:
        if "://" in text:
            text = URL_IN_TEXT.sub(lambda m: _address_masked(m.group(0)), text)
        if "?" in text:
            text = _QUERY_IN_TEXT.sub(_query_masked, text)
        if "/" in text:
            text = _PATH_IN_TEXT.sub(lambda m: f"/{m.group(1)}/***/***/", text)
        text = AUTH_LINE.sub(lambda m: f"{m.group(1)}{m.group(2)}***", text)
        text = BEARER.sub(lambda m: f"{m.group(1)} ***", text)
        text = MAC.sub("***", text)
        text = KEYVAL.sub(_value_masked, text)
        return redact(text)
    except Exception:
        return WITHHELD

def accepted_mark(path: str) -> str:
    """What ACCEPTED_KEY holds for *path*: its hash, not the path itself (a
    backup or a report of the settings names no folder)."""
    import hashlib
    return hashlib.sha256(os.path.abspath(path).encode("utf-8", "replace")).hexdigest()[:32]


def accepted_marks(value: Any) -> set[str]:
    """The marks ACCEPTED_KEY's *value* holds - one, or several apart."""
    return set(str(value or "").split())


def with_accepted(value: Any, path: str) -> str:
    """ACCEPTED_KEY's *value* with *path* gone on with too."""
    return " ".join(sorted(accepted_marks(value) | {accepted_mark(path)}))


def waiting(value: Any) -> list[str]:
    """The files of not_private() the person has not said to go on with,
    as ACCEPTED_KEY's *value* has it - every one, not the first alone."""
    marks = accepted_marks(value)
    return [p for p in not_private() if accepted_mark(p) not in marks]


def _theirs(path: str) -> bool:
    """Whether *path* (a link followed) is this user's own."""
    return os.stat(path).st_uid == os.geteuid()


def not_private() -> list[str]:
    """The settings files this start could not make readable by this user
    alone (their paths; empty when every one is)."""
    with _lock:
        return list(_not_private)

class LoginRefused(Exception):
    """A request to dopeiptv.org that held a login: not sent. Raised to the
    caller as requests' RequestException (core/_lazy_requests.py)."""


def _address_logins(text: str) -> set[str]:
    from .player_exec import LOGIN_WORDS
    out: set[str] = set()
    for line in str(text or "").splitlines():
        line = line.strip()
        if "://" not in line:
            continue
        if len(line) >= ADDRESS_LEAST:
            out.add(line)
        try:
            parts = urlsplit(line)
        except ValueError:
            continue
        info = parts.netloc.rpartition("@")[0]
        if info:
            user, _, password = info.partition(":")
            out |= {unquote(user), unquote(password)}
        for key, value in parse_qsl(parts.query, keep_blank_values=True):
            if unquote_plus(key).strip().lower() in LOGIN_WORDS:
                out.add(value)
    return out


def _header_logins(value: Any) -> set[str]:
    from .net_bridge import SAFE_HEADERS
    if isinstance(value, Mapping):
        pairs = [(str(k), str(v)) for k, v in value.items()]
    else:
        pairs = [(m.group(1), m.group(2)) for ln in str(value or "").splitlines()
                 if (m := _HEADER_LINE.match(ln))]
    out: set[str] = set()
    for name, val in pairs:
        if name.strip().lower() in SAFE_HEADERS | {"user-agent"} or not val:
            continue
        out.add(val)
        scheme, _, rest = val.partition(" ")
        if rest and scheme.isalpha():
            out.add(rest.strip())       # "Basic xxx", "Bearer xxx": the value alone too
    return out


def logins_of(playlists: Iterable[Any]) -> set[str]:
    """Every login the sources *playlists* hold (see the module's words)."""
    out: set[str] = set()
    for p in playlists or []:
        if not isinstance(p, Mapping):
            continue
        for key in _FIELDS:
            v = str(p.get(key) or "").strip()
            if v:
                out.add(v)
                if key == "mac":
                    out |= {v.lower(), v.upper(), v.replace(":", ""), v.lower().replace(":", "")}
        user, password = str(p.get("username") or ""), str(p.get("password") or "")
        if user and password:
            out |= basic_forms(user, password)
        for key in _ADDRESSES:
            out |= _address_logins(str(p.get(key) or ""))
        opts = p.get("options")
        if isinstance(opts, Mapping):
            for key in _ADDRESS_OPTIONS:
                out |= _address_logins(str(opts.get(key) or ""))
            if opts.get("headers"):
                out |= _header_logins(opts.get("headers"))
    return {v for v in out if v and v.strip()}


def _rebuild() -> None:
    global _long, _short_re
    values: set[str] = set()
    for v in _learnt | _never:
        values.add(v)
        values |= encoded_forms(v)
    _long = frozenset(v for v in values if len(v) >= LONG)
    short = sorted((v for v in values if len(v) < LONG), key=len, reverse=True)
    _short_re = (re.compile(r"(?<![A-Za-z0-9])(?:" + "|".join(map(re.escape, short))
                            + r")(?![A-Za-z0-9])") if short else None)


def learn(playlists: Iterable[Any], settings: Any = None) -> None:
    """The sources' logins known from now on - to this check and to the
    log's mask (core/log.register_secrets) before any client is made.
    *settings*: where the sources are kept, read again before a check."""
    global _learnt, _settings, _seen_raw
    rows = [p for p in playlists or [] if isinstance(p, Mapping)]
    found = logins_of(rows)
    for p in rows:
        # A user name with its password: the log masks the pair's HTTP
        # Basic too. Every other login alone - never a whole address,
        # which the log masks as an address already.
        register_secrets(str(p.get("username") or ""), str(p.get("password") or ""))
    for v in sorted(found):
        if "://" not in v:
            register_secrets(v)
    with _lock:
        if settings is not None:
            try:
                _settings = weakref.ref(settings)
            except TypeError:
                _settings = lambda s=settings: s      # noqa: E731
            _seen_raw = None
        if found - _learnt:
            _learnt = _learnt | found
            _rebuild()


def never(*values: str | None) -> None:
    """Values that never go to dopeiptv.org readable at all: the code that
    opens a synced copy, a room's code."""
    given = {str(v) for v in values if v and str(v).strip()}
    with _lock:
        if given - _never:
            _never.update(given)
            _rebuild()


def account_logins(settings: Any) -> set[str]:
    """The person's other logins the settings hold - every profile's: the
    watch-history and subtitle accounts' tokens and passwords, the sync
    code, Home Assistant's and a webhook's, Nerd's proxy and headers, a
    Kodi's password (core/backup.py's LOGIN_SETTINGS and the settings that
    hold one only sometimes)."""
    from .backup import _LOGIN_IN, LOGIN_SETTINGS
    plain = set(LOGIN_SETTINGS) - {"simkl_token_expires"}
    raw = settings.raw() if hasattr(settings, "raw") else settings
    try:
        keys = [str(k) for k in raw.allKeys()]
    except Exception:
        keys = []
    out: set[str] = set()
    for key in keys:
        name = key.rsplit("/", 1)[-1]
        if name not in plain and name not in _LOGIN_IN:
            continue
        try:
            value = raw.value(key, "")
        except Exception:
            continue
        if name == "nerd_proxy":
            out |= _address_logins(str(value or ""))
        elif name == "nerd_headers":
            out |= _header_logins(value)
        elif name == "kodi_devices":
            try:
                devices = json.loads(value) if isinstance(value, str) else value
            except ValueError:
                devices = []
            for d in devices if isinstance(devices, list) else []:
                if isinstance(d, Mapping) and d.get("password"):
                    out.add(str(d.get("password")))
        elif value and str(value).strip():
            out.add(str(value).strip())
    return out


#: What ``refusal`` says when the settings could not be read to check a
#: request: it fails closed - a login added since may be among them.
UNCHECKED = "the settings, which could not be read to check it"


def _fresh() -> bool:
    """The sources and accounts as the settings hold them now: one added,
    signed in or synced since the last ``learn`` is known before anything
    is sent. False when the settings handed to ``learn`` could not be read -
    the request is then not sent (``UNCHECKED``)."""
    global _seen_raw, _learnt
    ref = _settings
    s = ref() if ref is not None else None
    if s is None:
        return True
    try:
        raw = str(s.value("playlists", "") or "")
        accounts = account_logins(s)
    except Exception:
        return False
    stamp = raw + "\0" + "\0".join(sorted(accounts))
    if stamp == _seen_raw:
        return True
    try:
        rows = json.loads(raw) if raw else []
    except ValueError:
        rows = []
    learn(rows if isinstance(rows, list) else [])
    with _lock:
        if accounts - _learnt:
            _learnt = _learnt | accounts
            _rebuild()
    _seen_raw = stamp
    return True


def sealed(data: bytes | str) -> bytes | str:
    """*data* - bytes sealed under a key dopeiptv.org never has, or their
    base64 - left out of the next request's check that carries them.
    Returns *data*. Only core/sync.py and core/together.py call it, on
    what their seal made (tests/test_site_out.py)."""
    raw = data.encode("ascii") if isinstance(data, str) else bytes(data)
    now = time.monotonic()
    with _lock:
        _sealed[:] = [(t, b) for t, b in _sealed if now - t < SEALED_FOR_S][-(SEALED_MAX - 1):]
        _sealed.append((now, raw))
    return data


def _without_sealed(body: bytes) -> bytes:
    now = time.monotonic()
    with _lock:
        pieces = [b for t, b in _sealed if now - t < SEALED_FOR_S]
    for piece in sorted(pieces, key=len, reverse=True):
        if piece and piece in body:
            body = body.replace(piece, b"")
    return body


def _json_values(doc: Any, out: list[str], depth: int = 0) -> None:
    if depth > 32:
        out.append(json.dumps(doc))
    elif isinstance(doc, Mapping):
        for v in doc.values():
            _json_values(v, out, depth + 1)
    elif isinstance(doc, list):
        for v in doc:
            _json_values(v, out, depth + 1)
    elif doc is not None:
        out.append(str(doc))


def _service(url: str) -> bool:
    try:
        host = (urlsplit(url).hostname or "").lower().rstrip(".")
    except ValueError:
        return True             # an address that does not parse: looked at, not let by
    return host in HOSTS or any(host.endswith("." + h) for h in HOSTS)


def refusal(url: str, headers: Mapping[str, Any] | None = None,
            body: bytes | str | None = None) -> str | None:
    """Why the request to *url* may not be sent - the part of it that holds
    a login (never the login) - or None. Anything not for dopeiptv.org: None."""
    if not _service(url):
        return None
    if not _fresh():
        return UNCHECKED
    with _lock:
        long_, short_re = _long, _short_re
    if not long_ and short_re is None:
        return None
    anywhere: list[tuple[str, str]] = [("its address", unquote(url)), ("its address", url)]
    worded: list[tuple[str, str]] = []
    try:
        query = urlsplit(url).query
    except ValueError:
        query = ""
    worded += [("its address", v) for _k, v in parse_qsl(query, keep_blank_values=True)]
    for name, value in (headers or {}).items():
        if str(name).strip().lower() in OWN_HEADERS:
            continue
        text = value.decode("latin-1") if isinstance(value, bytes) else str(value)
        anywhere.append(("a header", f"{name}: {text}"))
        worded.append(("a header", text))
    if body is not None and not isinstance(body, (bytes, bytearray, str)):
        return "its body (a stream, not read)"     # none of the app's: not let by unread
    if body:
        raw = body.encode("utf-8") if isinstance(body, str) else bytes(body)
        raw = _without_sealed(raw)
        text = raw.decode("utf-8", "replace")
        anywhere.append(("its body", text))
        try:
            doc = json.loads(text)
        except (ValueError, RecursionError):
            worded.append(("its body", text))
        else:
            values: list[str] = []
            _json_values(doc, values)
            worded += [("its body", v) for v in values]
    for where, text in anywhere:
        if any(v in text for v in long_):
            return where
    if short_re is not None:
        for where, text in worded:
            if short_re.search(text):
                return where
    return None

def send(self, request: Any, stream: bool = False, *args: Any, **kwargs: Any) -> Any:
    # requests' own order: timeout, verify, cert, proxies.
    proxies = kwargs.get("proxies", args[3] if len(args) > 3 else None)
    # Offline mode: only this computer and the home network,
    # whoever asks - a redirect's hop too (core/offline.py).
    if offline.on():
        through = real.utils.select_proxy(request.url, proxies) if proxies else None
        for address in (str(request.url or ""), str(through or "")):
            why = offline.refusal(address) if address else ""
            if why:
                host = (offline._host_port(address) or ("?", 0))[0]
                offline.note_refused(host)
                raise OfflineRefused(f"offline mode: not sent to {host}",
                                     request=request)
    # Nothing for dopeiptv.org that holds a login of a source,
    # whoever asks (core/site_out.py) - a redirect's hop too.
    try:
        site_out.check(request.url, request.headers, request.body)
    except site_out.LoginRefused as e:
        raise LoginHeld(str(e), request=request) from None

def get_full(self, title: str, kind: str,
             callback: Callable[[dict], None]) -> dict | None:
    """Full metadata dict (poster_url/rating/imdb_id/cast), or None
    while the lookup is still pending."""
    if not title:
        return None
    key = self._key(title, kind)
    if key in self._cache:
        return self._cache[key]
    if key in self._failed:
        return {}
    if privacy.title_private(title) or offline.on():
        # What plays privately: TMDB is not asked about it (what it
        # answered before is above). No match, for now. Nor anything
        # while offline mode is on (core/offline.py).
        return {}
    self._waiting.setdefault(key, []).append(callback)
    self._ensure_fetch(title, kind, key)
    return None

def secure(url: str) -> bool:
    """Whether a request to one of dopeiptv.org's services may go to *url*:
    https to dopeiptv.org itself - or this computer, for the tests' own
    servers. Anything else is refused before a connection is made (a
    changed endpoint, a typo, another host)."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(str(url))
        host = (parts.hostname or "").lower()
    except ValueError:
        return False
    if host in _LOOPBACK:
        return parts.scheme in ("http", "https")
    return parts.scheme == "https" and host == SERVICE_HOST

def new_code() -> tuple[str, str]:
    """(code, its SHA-256): the code stays on this computer, the hash goes
    with the report - the one link between the two, naming nobody."""
    import hashlib
    import secrets
    code = secrets.token_urlsafe(24)
    return code, hashlib.sha256(code.encode("ascii")).hexdigest()


def code_hash(code: str) -> str:
    import hashlib
    return hashlib.sha256(code.encode("ascii")).hexdigest()

def fetch_replies(codes: list[str], timeout: float = 15.0, endpoint: str | None = None) -> dict | None:
    """{code: [answers]} for the codes whose reports were answered; None
    when the site could not be asked (never from a modified build). Only
    the hashes are sent."""
    if not build_check.allowed():
        return None
    by_hash = {code_hash(c): c for c in codes[:20]}
    try:
        status, data = _post(endpoint or REPLIES, json.dumps({"codes": list(by_hash)}).encode("utf-8"), timeout)
        if status != 200:
            raise OSError(f"HTTP {status}")
        got = json.loads(data or b"{}").get("replies") or {}
    except Exception as e:
        log.info("report: answers not asked (%s)", type(e).__name__)
        return None
    return {by_hash[h]: a for h, a in got.items() if h in by_hash and isinstance(a, list)}

def _answers_reply(self, code: str, text: str) -> None:
    """The person's reply to the answer that lets them, from its card:
    sent as feedback with the report's own code hash as its thread -
    scrubbed as feedback is, within feedback's limits, never from a
    modified build - and kept on the report here once the site took it;
    asked about soon after, as a new report is. The site saying the
    thread is closed (409) closes it here too."""
    settings = getattr(self, "settings", None)
    dlg = self._answers_window()
    if settings is None or not build_check.allowed():
        return
    now = time.time()
    wait = report.feedback_wait(report.sent_times(settings.value("feedback_sent", "")), now)
    if wait:
        if dlg is not None:
            dlg.reply_failed(code, wait)
        return
    personal = self._personal_values()
    words = report.scrub(text, personal).strip()[:report.REPLY_MAX]
    if not words:
        return
    h = report.code_hash(code)
    fields = {"reply": h, "thread": h}
    if dlg is not None:
        dlg.reply_sending(code)

    def done(status) -> None:
        win = self._answers_window()
        items = report.tickets(settings)
        ticket = next((t for t in items if t.get("c") == code), None)
        if status and 200 <= status < 300:
            at = time.time()
            keep = [t for t in report.sent_times(settings.value("feedback_sent", "")) if at - t < 86400]
            settings.setValue("feedback_sent", ",".join(str(int(t)) for t in [*keep, at]))
            if ticket is not None:
                report.add_followup(ticket, words, at)
                report.save_tickets(settings, items)
            self._schedule_answers()            # two minutes from now, as after a report
            if win is not None:
                win.reply_sent(code, report.tickets(settings))
            self._show_toast(tr("fba_reply_sent"), 5000)
            log.info("report: a reply to an answer sent by the person")
            return
        if status == 409:
            if ticket is not None and report.close_thread(ticket):
                report.save_tickets(settings, items)
            if win is not None:
                win.reply_failed(code, "closed", report.tickets(settings))
            return
        if win is not None:
            win.reply_failed(code, "failed")
    run_async(self.pool, partial(report.send_status, "feedback", words, personal=personal,
                                 extra=fields), done, lambda _e=None: done(0))

def accept(stats_dir: str, body: dict, build: str = "unknown") -> tuple[int, dict]:
    """One report from the app; (status, answer). *build*: what its
    X-dopeIPTV-Build header said (official.kind), never the body's word. A
    report already taken answers ok with "duplicate" (the app need not try
    again), and is not kept twice.

    With "thread" (a report's code hash) it is a follow-up to that report's
    latest answer: taken only while that answer lets them reply and they
    have not yet (409 "closed" otherwise, nothing kept); kept as a row of
    its own, tied to the report by its id, never by the hash."""
    thread = str(body.get("thread") or "")
    if thread and not _HASH.match(thread):
        return 400, {"error": "thread"}
    kind = "feedback" if thread else str(body.get("kind") or "feedback")
    if kind not in KINDS:
        kind = "feedback"
    version = str(body.get("version") or "")
    if not _VERSION.match(version):
        version = "?"
    system = re.sub(r"[^A-Za-z0-9 ._-]", "", str(body.get("os") or ""))[:24] or "?"
    site = kind == "feedback" and not thread and body.get("from") == "site"
    most = THREAD_TEXT if thread else MAX_TEXT
    # Cut before it is cleaned, with room for what the cleaning shortens
    # (an address to <address>), then again to what is kept.
    text = _cut(scrub(_head(str(body.get("text") or "").lstrip(), 2 * most)).strip()[:most],
                THREAD_BYTES if thread else SITE_BYTES if site else MAX_BYTES)
    if not text:
        return 400, {"error": "empty"}
    now = time.time()
    row = {"id": uuid.uuid4().hex[:12], "t": int(now), "kind": kind,
           "version": version, "os": system, "build": build if build in BUILDS else "unknown",
           "sig": "" if thread else signature(kind, text), "text": text}
    if not thread and _HASH.match(str(body.get("reply") or "")):
        row["reply"] = str(body["reply"])
    if kind == "feedback" and not thread:
        row.update({k: str(body.get(k)) for k, allowed in CHOICES.items() if body.get(k) in allowed})
        if site:
            row["from"] = "site"
    os.makedirs(stats_dir, exist_ok=True)
    path, _state = _paths(stats_dir)
    make_room(stats_dir)
    with _LOCK:
        try:
            if os.path.getsize(path) >= MAX_FILE:
                # Nothing could go (no report in it can be read): never past it.
                return 503, {"error": "full"}
        except OSError:
            pass
        mem = _memory(stats_dir, now)
        rid = to = None
        if thread:
            rid, to = _thread_of(stats_dir, thread)
            if rid is None:
                return 409, {"error": "closed"}
        same = _same(kind, text, rid or "")
        if same in mem["hashes"]:
            return 200, {"ok": True, "duplicate": True}
        if thread:
            if to is None:
                return 409, {"error": "closed"}
            row.update(thread_of=rid, to=to)
        if mem["n"] >= DAY_MOST:
            return 429, {"error": "enough for today"}
        sig = row["sig"]
        if kind != "feedback" and mem["sigs"].get(sig, 0) >= SAME_SIG_DAY:
            # Counted, so the problem's number stays right; its text is
            # already here many times over today.
            row["text"], row["counted"] = "", True
        elif mem["bytes"] + _bytes(row["text"]) > DAY_BYTES:
            # The day's room is used up (many long reports, or someone
            # filling it): this one keeps its start, enough to read it by.
            short = _cut(row["text"], LATE_BYTES)
            if short != row["text"]:
                row["text"], row["cut"] = short.rstrip() + " …", True
        mem["hashes"][same] = now
        mem["n"] += 1
        mem["sigs"][sig] = mem["sigs"].get(sig, 0) + 1
        mem["bytes"] += _bytes(row["text"])
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row, ensure_ascii=False) + "\n")
    if rid:
        # A reply waits to be read: out of the archive, unread (its own id
        # has no mark yet).
        archive(stats_dir, rid, False)
    return 200, {"ok": True, "id": row["id"]}

# Many people can share one address; a report is one press of Send.
if not _allowed("fb:" + addr, FEEDBACK_PER_WINDOW):
    return self._send(429, {"error": "slow down"})

def format_code(raw: bytes) -> str:
    """32 bytes as base32 in groups of four: 13 groups."""
    text = base64.b32encode(raw).decode("ascii").rstrip("=")
    return "-".join(text[i:i + 4] for i in range(0, len(text), 4))


def new_code() -> str:
    return format_code(secrets.token_bytes(32))

def hkdf(ikm: bytes, salt: bytes, info: bytes, length: int) -> bytes:
    """HKDF-SHA256 (RFC 5869)."""
    if not 0 < length <= 255 * 32:
        raise ValueError("HKDF-SHA256 makes 1 to 8160 bytes")
    prk = hmac.new(salt or b"\0" * 32, ikm, hashlib.sha256).digest()
    out, block = b"", b""
    counter = 1
    while len(out) < length:
        block = hmac.new(prk, block + info + bytes([counter]), hashlib.sha256).digest()
        out += block
        counter += 1
    return out[:length]


def derive(raw: bytes) -> tuple[str, bytes]:
    """(slot, key) for a code: the slot the site keeps it under (64 hex)
    and the encryption key, each from its own HKDF label - knowing one says
    nothing about the other."""
    slot = hkdf(raw, _SALT, b"slot", 32).hex()
    return slot, hkdf(raw, _SALT, b"key", 32)


def auth_of(raw: bytes) -> str:
    """The credential a request to the code's slot carries (64 hex): from a
    label of its own, so neither the slot nor the key says anything of it,
    and the site keeps only its SHA-256."""
    return hkdf(raw, _SALT, b"auth", 32).hex()

def seal(key: bytes, doc: dict[str, Any]) -> bytes:
    """The snapshot as the site keeps it: a format byte, a random nonce and
    the compressed JSON, encrypted and authenticated."""
    plain = zlib.compress(_canon(doc).encode("utf-8"), 6)
    nonce = secrets.token_bytes(12)
    head = bytes([FORMAT])
    return head + nonce + aead.encrypt(key, nonce, plain, _AAD + head)


def unseal(key: bytes, blob: bytes) -> dict[str, Any]:
    if not blob:
        raise SyncError("read")
    if blob[0] > FORMAT:
        raise SyncError("newer")
    if blob[0] != FORMAT or len(blob) < 1 + 12 + 16:
        raise SyncError("read")
    try:
        plain = aead.decrypt(key, blob[1:13], blob[13:], _AAD + blob[:1])
        inflate = zlib.decompressobj()
        text = inflate.decompress(plain, _MAX_PLAIN)
        if inflate.unconsumed_tail:
            raise ValueError("too big")
        doc = json.loads(text.decode("utf-8"))
    except (ValueError, RecursionError, zlib.error, UnicodeDecodeError) as e:
        raise SyncError("read") from e
    if not isinstance(doc, dict) or not isinstance(doc.get("c"), dict):
        raise SyncError("read")
    # The layout's number as another computer wrote it: one that is no
    # number ("x", 1e400, a list) is no copy this app wrote - int() of it
    # raised (tests/test_fuzz_readers.py).
    try:
        version = int(doc.get("v") or 0)
    except (TypeError, ValueError, OverflowError):
        raise SyncError("read") from None
    if version > FORMAT:
        raise SyncError("newer")
    clean = empty_doc()
    for cat, entries in doc["c"].items():
        if isinstance(entries, dict):
            clean["c"][str(cat)] = {
                str(k): e for k, e in entries.items()
                if isinstance(e, dict) and isinstance(e.get("t"), int)
                and ("v" in e or e.get("d") == 1)}
    return clean

def keep_private(path: str, *, folder: bool = True, create: bool = True) -> bool:
    """*path* readable by this user alone, and with *folder* the folder it is
    in too (made at 0700 when missing). *create*: a missing file made empty
    at 0600 first. Never raises; False when it could not be done - logged
    with the file's name and kept in not_private()."""
    if os.name != "posix" or not path:
        return True
    try:
        kept = True
        if folder:
            parent = os.path.dirname(path)
            os.makedirs(parent, mode=FOLDER_MODE, exist_ok=True)
            if not _theirs(parent):
                _note(path, "its folder is another account's")
                return False
            kept = _narrow(parent, FOLDER_MODE)
        if os.path.islink(path) and not os.path.exists(path):
            # A link to nothing: what is written there lands where it
            # points, which nothing here has made private.
            _note(path, "a link to a file that is not there")
            return False
        if create and not os.path.lexists(path):
            try:
                os.close(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, FILE_MODE))
            except FileExistsError:
                pass
        if os.path.exists(path):
            if not _theirs(path):
                _note(path, "another account owns it")
                return False
            kept = _narrow(path, FILE_MODE) and kept
        if not kept:
            _note(path, "its drive keeps no permissions")
        return kept
    except OSError as e:
        _note(path, e.strerror or type(e).__name__)
        return False


def protect(stores: Mapping[str, Any] | None = None) -> None:
    """Every settings file of the app kept to this user (core/backup's
    open_stores: the main settings, resume, follow, cache). Never in the way
    of starting."""
    if os.name != "posix":
        return
    try:
        from PyQt6.QtCore import QSettings

        from .. import ORG
        if stores is None:
            from .backup import open_stores
            stores = open_stores()
        for s in stores.values():
            path = str(s.fileName())
            plain = s.format() == QSettings.Format.IniFormat or sys.platform != "darwin"
            own = os.path.basename(os.path.dirname(path)) == ORG
            keep_private(path, folder=plain and own, create=plain)
    except Exception as e:
        log.warning("settings: not kept to this user (%s)", e)

def counter(doc: dict[str, Any]) -> int:
    e = (doc["c"].get(_META) or {}).get(_COUNTER)
    if not isinstance(e, dict) or not isinstance(e.get("v"), int):
        return 0
    return max(0, int(e["v"]))

def _counted(doc: dict[str, Any], n: int, saved: int = 0) -> dict[str, Any]:
    """*doc* with the counter *n* - and, with *saved*, the time it is put
    there (its categories copied, so a shared one is not changed)."""
    out = _copy(doc)
    meta = dict(out["c"].get(_META) or {}, **{_COUNTER: {"t": n, "v": n}})
    if saved >= _EPOCH:
        meta[_SAVED] = {"t": saved, "v": saved}
    out["c"][_META] = meta
    return out

def auth_of(raw: bytes) -> str:
    """The credential a request to the code's slot carries (64 hex): from a
    label of its own, so neither the slot nor the key says anything of it,
    and the site keeps only its SHA-256."""
    return hkdf(raw, _SALT, b"auth", 32).hex()

def __init__(self, slot: str, endpoint: str | None = None,
             timeout: float = 20.0, auth: str = "") -> None:
    self.url = (endpoint or ENDPOINT) + slot
    self.timeout = timeout
    from .. import __version__
    self.headers = {"User-Agent": f"dopeIPTV/{__version__}",
                    "Content-Type": "application/json", **build_check.headers()}
    if auth:
        self.headers[AUTH_HEADER] = auth

@classmethod
def of(cls, raw: bytes, endpoint: str | None = None, timeout: float = 20.0) -> Remote:
    """The site's side of the code *raw*: its slot, with its credential."""
    return cls(derive(raw)[0], endpoint, timeout, auth=auth_of(raw))

def _call(self, method: str, body: dict | None = None) -> Any:
    from ._lazy_requests import requests
    if not build_check.allowed():
        # Never asked from a modified build: the site refuses it anyway.
        raise SyncError("modified")
    if not build_check.secure(self.url):
        log.warning("sync: not https - nothing sent")
        raise SyncError("net")
    try:
        # Never followed elsewhere: a copy goes to the slot named, or
        # nowhere.
        return requests.request(method, self.url, headers=self.headers,
                                data=None if body is None
                                else json.dumps(body).encode("ascii"),
                                timeout=self.timeout, allow_redirects=False)
    except Exception as e:
        log.info("sync: %s not answered (%s)", method, type(e).__name__)
        raise SyncError("net") from e

def secure(url: str) -> bool:
    """Whether a request to one of dopeiptv.org's services may go to *url*:
    https to dopeiptv.org itself - or this computer, for the tests' own
    servers. Anything else is refused before a connection is made (a
    changed endpoint, a typo, another host)."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(str(url))
        host = (parts.hostname or "").lower()
    except ValueError:
        return False
    if host in _LOOPBACK:
        return parts.scheme in ("http", "https")
    return parts.scheme == "https" and host == SERVICE_HOST

class Refused(Exception):
    """The slot is bound to a credential and the request did not carry it."""


def _seal(auth: str) -> str:
    """What is kept of a credential: its SHA-256."""
    return hashlib.sha256(auth.encode("ascii")).hexdigest()


def _check(data: dict | None, auth: str) -> None:
    """Refused unless the slot is unbound or *auth* is its credential."""
    kept = data.get("auth") if data else None
    if kept and not (auth and hmac.compare_digest(_seal(auth), str(kept))):
        raise Refused()

def get(stats_dir: str, slot: str, auth: str = "") -> dict | None:
    """{"version", "t", "blob"} kept under *slot*, or None. Refused when
    the slot is bound and *auth* is not its credential."""
    path = _path(stats_dir, slot)
    with _lock(slot):
        data = _read(path)
        if data is None:
            return None
        _check(data, auth)
        try:
            if time.time() - os.path.getmtime(path) > TOUCH_SECS:
                os.utime(path)
        except OSError:
            pass
    return {"version": data["version"], "t": int(data.get("t") or 0), "blob": data["blob"]}


def put(stats_dir: str, slot: str, version_seen: object, blob: object,
        auth: str = "") -> tuple[int, dict]:
    """Keep *blob* as the next version of *slot* - if *version_seen* is the
    version kept now (0: none yet). A new slot is refused while all the
    slots keep MAX_TOTAL; one there already can still be written. A bound
    slot takes only its credential (403, before anything of it is said);
    an unbound one is bound to *auth* when one comes. (status, body to
    answer)."""
    path = _path(stats_dir, slot)
    if not isinstance(version_seen, int) or isinstance(version_seen, bool) or version_seen < 0:
        return 400, {"error": "version_seen"}
    size = blob_size(blob)
    if size > MAX_BLOB:
        return 413, {"error": "too big", "most": MAX_BLOB}
    if size < MIN_BLOB:
        return 400, {"error": "blob"}
    with _lock(slot):
        cur = _read(path)
        try:
            _check(cur, auth)
        except Refused:
            return 403, {"error": "refused"}
        version = cur["version"] if cur else 0
        if version_seen != version:
            body: dict = {"error": "conflict", "version": version,
                          "t": int(cur.get("t") or 0) if cur else 0}
            if cur:
                body["blob"] = cur["blob"]
            return 409, body
        if cur is None and usage(stats_dir)["bytes"] + size > MAX_TOTAL:
            return 507, {"error": "full"}
        before = _size(path) if cur else 0
        grows = len(str(blob)) - len(cur["blob"]) if cur else 0
        if grows > 0 and usage(stats_dir)["bytes"] + grows > MAX_TOTAL * GROW_SHARE:
            # Rewritten no larger it would still be taken: a household that
            # syncs goes on syncing while the space is full.
            return 507, {"error": "full"}
        now = int(time.time())
        kept = {"version": version + 1, "t": now, "blob": blob}
        bound = (cur or {}).get("auth") or (_seal(auth) if auth else "")
        if bound:
            kept["auth"] = bound
        _write(path, kept)
        _changed(stats_dir, _size(path) - before, 0 if cur else 1)
    return 200, {"version": version + 1, "t": now}


def delete(stats_dir: str, slot: str, auth: str = "") -> bool:
    """Remove *slot*. Refused when it is bound and *auth* is not its
    credential."""
    path = _path(stats_dir, slot)
    with _lock(slot):
        _check(_read(path), auth)
        size = _size(path)
        try:
            os.unlink(path)
        except FileNotFoundError:
            return False
        _changed(stats_dir, -size, -1)
        return True

def _sync(self) -> None:
    """Someone's encrypted copy under a slot (sync.py), for anyone: no
    account. The address is never kept, logged or tied to the slot: the
    limits hold it in memory only."""
    if self._refused("sync"):
        return
    import sync
    slot = self.path.split("?", 1)[0][len(SYNC):]
    if not sync.SLOT.match(slot):
        return self._send(404, {"error": "not found"})
    addr = self.headers.get("X-Real-IP") or "local"
    if not _allowed("sync:" + addr, SYNC_PER_WINDOW):
        return self._send(429, {"error": "slow down"})
    if self.command != "GET" and not _allowed("sync-w:" + addr, SYNC_WRITES_PER_WINDOW):
        return self._send(429, {"error": "slow down"})
    where = _stats_dir()
    auth = self.headers.get("X-Sync-Auth") or ""
    if auth and not sync.AUTH.match(auth):
        return self._send(400, {"error": "auth"})
    try:
        if self.command == "GET":
            got = sync.get(where, slot, auth)
            return self._send(200, got) if got else self._send(404, {"error": "none"})
        if self.command == "DELETE":
            return self._send(200, {"deleted": sync.delete(where, slot, auth)})
    except sync.Refused:
        return self._send(403, {"error": "refused"})
    try:
        length = int(self.headers.get("Content-Length") or 0)
    except ValueError:
        length = -1
    if length > sync.MAX_BODY:
        self.close_connection = True
        return self._send(413, {"error": "too big", "most": sync.MAX_BLOB})
    if length <= 0:
        return self._send(400, {"error": "body"})
    try:
        data = json.loads(self.rfile.read(length))
    except (ValueError, TypeError, RecursionError):
        return self._send(400, {"error": "body"})
    if not isinstance(data, dict):
        return self._send(400, {"error": "body"})
    if not sync.exists(where, slot) and not _allowed("sync-new:" + addr, SYNC_NEW_PER_DAY, DAY):
        return self._send(429, {"error": "slow down"})
    try:
        status, body = sync.put(where, slot, data.get("version_seen"), data.get("blob"), auth)
    except OSError as e:
        print(f"[donate] sync: not stored ({type(e).__name__})", file=sys.stderr, flush=True)
        return self._send(503, {"error": "not stored"})
    if status == 200:
        try:
            sync_watch(where)
        except Exception as e:  # noqa: BLE001 - a warning never stops a write
            print(f"[donate] sync space: {type(e).__name__}", file=sys.stderr, flush=True)
    return self._send(status, body)

def new_code() -> str:
    raw = "".join(secrets.choice(ALPHABET) for _ in range(CODE_LEN))
    return format_code(raw)

def is_old_code(text: str) -> bool:
    """Whether *text* is one of the short codes 1.6.7 made (about 40 bits):
    never joined - the window says why, so nobody takes it for a typo."""
    s = _raw(text)
    return len(s) == OLD_LEN and all(ch in ALPHABET for ch in s)


@functools.lru_cache(maxsize=8)
def _stretched(code: str) -> bytes:
    """The code after STRETCH rounds: what derive and auth_of take apart."""
    shown = parse_code(code)
    if shown is None:
        raise ValueError("not a room code")
    raw = shown.replace("-", "")
    # Whoever has the code is in the room: never in a log.
    register_secrets(shown, raw, shown.lower())
    site_out.never(shown, raw, shown.lower())
    return hashlib.pbkdf2_hmac("sha256", raw.encode("ascii"), _SALT, STRETCH, 32)


@functools.lru_cache(maxsize=8)
def derive(code: str) -> tuple[str, bytes]:
    """(room id, key) for a code: the name the relay keeps the room's
    messages under (64 hex) and the key they are sealed with, each from its
    own HKDF label - one says nothing about the other."""
    seed = _stretched(code)
    return hkdf(seed, _SALT, b"room", 32).hex(), hkdf(seed, _SALT, b"key", 32)


def auth_of(code: str) -> str:
    """The credential every request to the code's room carries (64 hex):
    from a label of its own, so neither the room id nor the key says
    anything of it, and from the stretched code, so the hash the relay
    keeps of it is as hard to guess a code from as the room id."""
    auth = hkdf(_stretched(code), _SALT, b"auth", 32).hex()
    register_secrets(auth)
    return auth

def seal(key: bytes, room: str, msg: dict[str, Any], identity: Identity | None = None) -> bytes:
    """*msg* as the relay passes it: a format byte, a random nonce, and the
    padded JSON (signed, with *identity*), encrypted and tied to the room."""
    return _seal_text(key, room, encode(msg, room, identity))


def _seal_text(key: bytes, room: str, text: bytes) -> bytes:
    size = next((p for p in _PAD if p >= len(text) + 2), 0)
    if not size:
        raise ValueError("message too long")
    plain = struct.pack(">H", len(text)) + text + b"\0" * (size - 2 - len(text))
    nonce = secrets.token_bytes(12)
    head = bytes([FORMAT])
    return head + nonce + aead.encrypt(key, nonce, plain, _AAD + head + bytes.fromhex(room))


def _open_text(key: bytes, room: str, blob: Any) -> bytes | None:
    """The JSON text sealed in *blob*, or None: another key, damaged, a
    newer format - or not exactly as seal() makes one (a size that is none
    of _PAD, anything but zeros after the text): nothing rides along."""
    if not isinstance(blob, (bytes, bytearray)) or not MIN_FRAME <= len(blob) <= MAX_FRAME:
        return None
    if blob[0] != FORMAT:
        return None
    try:
        plain = aead.decrypt(key, bytes(blob[1:13]), bytes(blob[13:]),
                             _AAD + bytes(blob[:1]) + bytes.fromhex(room))
    except ValueError:
        return None
    if len(plain) not in _PAD:
        return None
    (length,) = struct.unpack(">H", plain[:2])
    if length > len(plain) - 2 or any(plain[2 + length:]):
        return None
    return plain[2:2 + length]

def open_frame(key: bytes, room: str, blob: bytes) -> dict[str, Any] | None:
    """The message in *blob* as sent, unchecked (open_message checks who
    sent it), or None for anything that is not one of this room's."""
    return _loads(_open_text(key, room, blob))

@dataclass(frozen=True)
class Identity:
    """This computer in one room: an Ed25519 key pair made for it, and the
    id the others know it by - the hash of the public key, so only the
    holder of *seed* can speak under it."""
    seed: bytes
    public: bytes
    id: str

    def __repr__(self) -> str:
        return f"Identity({self.id})"


def member_of(public: bytes) -> str:
    """The id of the member whose public key is *public* (ID_LEN hex)."""
    return hashlib.sha256(_ID_CTX + public).hexdigest()[:ID_LEN]


def new_identity() -> Identity:
    """This computer's key and id in a room, new for every room it joins."""
    seed = secrets.token_bytes(32)
    public = ed25519.public_key(seed)
    return Identity(seed, public, member_of(public))


# -- a message, sealed ----------------------------------------------------------------

def _signed(room: str, body: bytes) -> bytes:
    return _SIGN_CTX + bytes.fromhex(room) + body


def encode(msg: dict[str, Any], room: str = "", identity: Identity | None = None) -> bytes:
    """*msg* as JSON. With *identity* (whose id must be the message's
    sender) the public key is added and, as the last field, the signature
    over the room and every byte before it - checked on exactly those
    bytes (_signature_holds), so nothing depends on two computers writing
    JSON alike."""
    if identity is None:
        return json.dumps(msg, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    if msg.get("f") != identity.id:
        raise ValueError("not this member's message")
    signed = {k: v for k, v in msg.items() if k not in ("pk", "sg")}
    signed["pk"] = base64.b64encode(identity.public).decode("ascii")
    body = json.dumps(signed, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    sig = base64.b64encode(ed25519.sign(identity.seed, _signed(room, body)))
    return body[:-1] + _SIG_HEAD + sig + b'"}'


def _signature_holds(room: str, text: bytes, d: dict[str, Any], sender: str) -> bool:
    """Whether *text* (the JSON *d* was read from) is signed by the key
    its sender's id is the hash of."""
    tail = text[-_SIG_TAIL:]
    if len(text) <= _SIG_TAIL or not tail.startswith(_SIG_HEAD) or not tail.endswith(b'"}'):
        return False
    sig_text = tail[len(_SIG_HEAD):-2]
    pk_text = d.get("pk")
    if (not isinstance(pk_text, str) or len(pk_text) != 44
            or d.get("sg") != sig_text.decode("ascii", "replace")):
        return False
    try:
        public = base64.b64decode(pk_text, validate=True)
        sig = base64.b64decode(sig_text, validate=True)
    except ValueError:
        return False
    if len(public) != 32 or len(sig) != 64 or member_of(public) != sender:
        return False
    return ed25519.verify(public, _signed(room, text[:-_SIG_TAIL] + b"}"), sig)

def open_message(key: bytes, room: str, blob: bytes) -> Message | None:
    """The message in *blob*, well formed and from who it says: with the
    signature of the key its sender's id is the hash of. None for anything
    else - an older app's unsigned message among them."""
    text = _open_text(key, room, blob)
    d = _loads(text)
    msg = parse(d)
    if msg is None or text is None or d is None:
        return None
    if not _signature_holds(room, text, d, msg.sender):
        log.debug("together: a message not signed by its sender was dropped")
        return None
    return dataclasses.replace(msg, signed=True)

def remembered(code: str) -> dict[str, tuple[int, float]]:
    """The counters taken in room *code* this run (a Room's ``_last_n``):
    the same dict each time it is joined, so a message taken before a
    rejoin is not taken again. Never written anywhere."""
    with _REMEMBERED_LOCK:
        seen = _REMEMBERED.pop(code, None)
        if seen is None:
            seen = {}
        _REMEMBERED[code] = seen
        while len(_REMEMBERED) > ROOMS_REMEMBERED:
            _REMEMBERED.popitem(last=False)
        return seen

# -- in
def _timely(self, msg: Message) -> bool:
    """Whether *msg* is from this stay in the room and from about now
    (the module's docstring says why each bound). Without the relay's
    clock nothing can be said, and nothing is refused."""
    if not self.clock.known:
        return True
    relay_now = self.clock.now_ms()
    if not relay_now - STALE_MS <= msg.t <= relay_now + AHEAD_MS:
        return False
    return msg.t >= self.clock.now_ms(self._born) - JOIN_SLACK_MS

def _counted(self, msg: Message, now: float) -> bool:
    """Whether *msg* is new from its sender - and its number kept."""
    last = self._last_n.get(msg.sender)
    if last is not None and msg.n <= last[0]:
        return False
    if last is None and len(self._last_n) >= SENDERS_MAX:
        keep = (STALE_MS + AHEAD_MS) / 1000.0
        for sender in [s for s, (_n, at) in self._last_n.items()
                       if now - at > keep and s not in self.members]:
            del self._last_n[sender]
        if len(self._last_n) >= SENDERS_MAX:
            return False
    self._last_n[msg.sender] = (msg.n, now)
    return True

def _prove(self, sender: str, now: float) -> bool:
    """*sender* named this computer: taken from now on - unless the
    room remembers SENDERS_MAX others it cannot let go."""
    if sender not in self._proven and len(self._proven) >= SENDERS_MAX:
        keep = (STALE_MS + AHEAD_MS) / 1000.0
        for s in [s for s, at in self._proven.items()
                  if now - self._last_n.get(s, (0, at))[1] > keep and s not in self.members]:
            del self._proven[s]
        if len(self._proven) >= SENDERS_MAX:
            return False
    self._proven[sender] = now
    return True

def _answer(self, sender: str, now: float, every: float) -> list[tuple[str, Any]]:
    """("answer", *sender*): an answer naming it is to go out - not
    within *every* seconds of the last, nor for more than SENDERS_MAX
    senders at once."""
    last = self._answered.get(sender)
    if last is not None and now - last < every:
        return []
    if last is None and len(self._answered) >= SENDERS_MAX:
        keep = (STALE_MS + AHEAD_MS) / 1000.0
        for s in [s for s, at in self._answered.items() if now - at > keep]:
            del self._answered[s]
        if len(self._answered) >= SENDERS_MAX:
            return []
    self._answered[sender] = now
    return [("answer", sender)]

def _not_yet(self, msg: Message, now: float) -> list[tuple[str, Any]]:
    """A sender of PROTO that has not named this computer: nothing of
    it is taken - it may be saying what it said before this stay began.
    Its hello is answered and, should it speak on, it is asked now and
    then, naming it either way: that brings the answer that names this
    computer."""
    if msg.kind == "hi" and not msg.answer:
        return self._answer(msg.sender, now, HELLO_EVERY)
    return self._answer(msg.sender, now, NUDGE_EVERY)

def receive(self, msg: Message, now: float) -> list[tuple[str, Any]]:
    """What *msg* changes, as events: ("joined" | "left" | "status" |
    "hello", Member), ("state", (old, new)), ("answer", sender) - an
    answer naming *sender* is to go out -, ("unsigned", None) - once a
    room, for the first message no key signs (an app up to 1.6.8) or
    that says no PROTO (an app up to 1.6.10), left out until it is
    updated. Nothing for one of this computer's own,
    an old one handed again, one out of its time, or one of a sender of
    PROTO said before it named this computer."""
    if msg.sender == self.me:
        return []
    if not msg.signed or msg.proto < PROTO:
        # An older app's: unsigned, or with no guard against an old
        # message handed again but the relay's clock.
        log.debug("together: a message of an older app was dropped")
        if not self._told_unsigned:
            self._told_unsigned = True
            return [("unsigned", None)]
        return []
    if not self._timely(msg):
        log.debug("together: a message out of its time was ignored")
        return []
    first = msg.proto >= PROTO and msg.sender not in self._proven
    if first and msg.to != self.me:
        return self._not_yet(msg, now)
    if not self._counted(msg, now):

def _poll_loop(self) -> None:
    relay = self._poll_relay = self._relay_for(self.room, self.me)
    after, first, fails = 0, True, 0
    while not self._stop.is_set():
        sent = time.monotonic()
        try:
            got = relay.poll(after, 0.0 if first else WAIT)
        except RelayError as e:
            if self._stop.is_set():
                break
            fails += 1
            self._tell(e.kind)
            if e.kind == "modified":
                break
            self._stop.wait(self.BACKOFF[min(fails, len(self.BACKOFF)) - 1])
            continue
        except Exception:
            log.warning("together: poll failed", exc_info=True)
            self._stop.wait(self.BACKOFF[-1])
            continue
        received = time.monotonic()
        if self._stop.is_set():
            break
        fails = 0
        if first:
            # Only an answer the relay did not hold back times its clock.
            self.clock.sample(sent, got.now, received)
        if got.reset:
            log.info("together: the relay started the room over")
        msgs = got.msgs[-BATCH_MAX:]
        if first and not self._posted.is_set():
            if msgs:
                log.debug("together: %d messages from before joining left unread", len(msgs))
            msgs = []
        self._polled.set()
        if got.older:
            self._tell_older()
        for _seq, blob in msgs:
            if self._stop.is_set():
                break
            msg = open_message(self.key, self.room, blob)
            if msg is None and not self._older_told and self._on_older is not None \
                    and older_frame(self.key, self.room, blob):
                self._tell_older()
            if msg is None or msg.sender == self.me:
                continue
            try:
                self._on_message(msg)
            except Exception:
                log.debug("together: message not delivered", exc_info=True)
        after = got.seq
        self._tell("ok", got.members)
        if not first and not got.msgs and received - sent < 1.0:
            self._stop.wait(2.0)        # the relay did not wait: no busy loop
        first = False
    self._polled.set()
    if hasattr(relay, "close"):
        relay.close()

def _seal(auth: str) -> str:
    """What is kept of a room's credential: its SHA-256."""
    return hashlib.sha256(auth.encode("ascii")).hexdigest()

def _admit(self, room: _Room, member: str, auth: str, now: float, bind: bool = True) -> bool:
    """Whether *member* may use *room*: an unbound room takes anyone, and
    the first credential binds it (*bind*); a bound one takes its own
    credential, or a member seated without one before it was bound, for
    as long as it keeps its seat. Compared in constant time."""
    self._expire(room, now)
    if not room.auth:
        if auth and bind:
            room.auth = _seal(auth)
            room.open = set(room.members) - {member}
        return True
    if auth:
        return hmac.compare_digest(_seal(auth), room.auth)
    if member in room.open:
        return True
    room.refused = now
    return False

@staticmethod
def _paced(room: _Room, member: str, now: float) -> bool:
    """Whether *member* may post now: MAX_PER_MINUTE in a minute."""
    times = room.sent.setdefault(member, deque())
    while times and now - times[0] >= 60.0:
        times.popleft()
    if len(times) >= MAX_PER_MINUTE:
        return False
    times.append(now)
    return True

# -- the requests
def post(self, rid: str, member: str, blob: bytes, auth: str = "",
         addr: str = "") -> tuple[int, dict]:
    bad = self._checked(rid, member, auth)
    if bad:
        return bad
    if not isinstance(blob, (bytes, bytearray)) or len(blob) > MAX_MESSAGE:
        return 413, {"error": "too big", "most": MAX_MESSAGE}
    if len(blob) < MIN_MESSAGE:
        return 400, {"error": "message"}
    now = self._clock()
    with self._lock:
        room, status = self._room(rid, now, addr)
        if room is None:
            return status, {"error": "busy" if status == 503 else "slow down"}
        if not self._admit(room, member, auth, now):
            return 403, {"error": "refused"}
        room.touched = now
        if not self._seat(room, member, now):
            return 403, {"error": "full", "most": MAX_MEMBERS}
        if not self._paced(room, member, now):
            return 429, {"error": "slow down"}
        room.seq += 1
        room.msgs.append((room.seq, member, bytes(blob)))
        room.size += len(blob)
        while room.msgs and (len(room.msgs) > KEEP_MESSAGES or room.size > ROOM_BYTES):
            room.size -= len(room.msgs.popleft()[2])
        room.cond.notify_all()
        return 200, self._answer(room, auth)

def _together(self) -> None:
    """Watch together's relay (together.py): a room's sealed messages,
    in memory only. Neither the room, the member, the room's credential
    nor the address is kept beyond memory or logged (the rate limit
    holds the address; the room, its credential's hash). An IPv6
    address counts by its /64."""
    if self._refused("together"):
        return
    import together
    path, _, query = self.path.partition("?")
    room = path[len(TOGETHER):]
    if not together.ROOM.match(room):
        return self._send_quiet(404, {"error": "not found"})
    member = (self.headers.get(together.MEMBER_HEADER) or "").strip().lower()
    if not together.MEMBER.match(member):
        return self._send_quiet(400, {"error": "member"})
    # From 1.6.11; an older app sends none (together.py says what then).
    auth = (self.headers.get(together.AUTH_HEADER) or "").strip().lower()
    if auth and not together.AUTH.match(auth):
        return self._send_quiet(400, {"error": "auth"})
    addr = together.where(self.headers.get("X-Real-IP") or "local")
    if not _allowed("tg:" + addr, TOGETHER_PER_WINDOW):
        return self._send_quiet(429, {"error": "slow down"})
    # Asking for a room that is not there makes it: without a limit of
    # its own one address filled every room there is (leaving is no room).
    if self.command != "DELETE" and not together.RELAY.has(room) \
            and not _allowed("tg-new:" + addr, TOGETHER_NEW_PER_WINDOW):
        return self._send_quiet(429, {"error": "slow down"})
    if self.command == "GET":
        args = {k: v[0] for k, v in urllib.parse.parse_qs(query).items()}
        try:
            after = int(args.get("after", "0"))
            wait = float(args.get("wait", "0"))
        except ValueError:
            return self._send_quiet(400, {"error": "after or wait"})
        if wait != wait:                     # NaN
            return self._send_quiet(400, {"error": "after or wait"})
        return self._send_quiet(*together.RELAY.poll(room, member, after, wait, addr, auth))
    if self.command == "DELETE":
        return self._send_quiet(*together.RELAY.leave(room, member, auth))
    try:
        length = int(self.headers.get("Content-Length") or 0)
    except ValueError:
        length = -1
    if length > together.MAX_MESSAGE:
        self.close_connection = True
        return self._send_quiet(413, {"error": "too big", "most": together.MAX_MESSAGE})
    if length <= 0:
        return self._send_quiet(400, {"error": "body"})
    blob = self.rfile.read(length)
    return self._send_quiet(*together.RELAY.post(room, member, blob, auth, addr))

def record(self, group: str, key, pos: float, dur: float,
           item: dict | None = None,
           series_ctx: dict | None = None) -> None:
    """Store (or drop) a resume point for *group:key*. Positions in the
    first minute or past 95% of the runtime are dropped, not saved - the
    user is effectively at the start or the end. For movies and episodes an
    *item* snapshot is kept (plus the episode's *series_ctx*) so the
    'Continue watching' list can render and replay it."""
    if privacy.private_key(key):
        # Private viewing, or the private playback of this title going
        # on after it ended: where it stopped is not kept - the store's
        # own check, whoever calls.
        return
    rkey = f"{group}:{key}"
    if dur > 0 and 60 < pos < dur * 0.95:
        entry: dict[str, Any] = {"pos": round(pos), "dur": round(dur),
                                 "ts": int(time.time())}
        if group in ("vod", "episode") and item:
            snap = {k: item[k] for k in _SNAP_FIELDS
                    if item.get(k) is not None}
            sname = (series_ctx or {}).get("name") or (series_ctx or {}).get("title")
            if isinstance(snap.get("name"), str):
                snap["name"] = collapse_repeats(snap["name"])
            if group == "episode" and sname and snap.get("name"):
                # The episode's own name: a Continue watching row has the
                # series' in front, and kept so it would say it twice.
                snap["name"] = without_series(str(snap["name"]), str(sname)) or snap["name"]
            if snap:
                entry["item"] = snap
            if group == "episode" and series_ctx:
                ctx = {k: series_ctx[k] for k in _CTX_FIELDS
                       if series_ctx.get(k) is not None}
                if ctx:
                    entry["ctx"] = ctx
        else:
            # Preserve any existing snapshot when we only have position.
            old = self._data.get(rkey) or {}
            if old.get("item"):
                entry["item"] = old["item"]
            if old.get("ctx"):
                entry["ctx"] = old["ctx"]
        self._data[rkey] = entry
    else:
        self._data.pop(rkey, None)
    self._settings.setValue(self._key, json.dumps(self._data))

def in_memory(path: Path | str, mounts: str | None = None) -> bool:
    """Whether *path* is on a file system in memory (tmpfs, ramfs)."""
    return mount_of(path, mounts)[1] in IN_MEMORY

def encrypted_block(name: str, sys_root: str = SYS, depth: int = 0) -> bool:
    """Whether block device *name* keeps nothing readable without its key:
    zram without a backing device, a dm-crypt mapping, or a mapping (LVM,
    RAID...) whose every part is one of those."""
    if depth > _DEPTH or not name or "/" in name or name.startswith("."):
        return False
    block = os.path.join(sys_root, "class", "block", name)
    if name.startswith("zram"):
        # No backing_dev at all: a kernel without zram writeback, so nothing
        # of it can reach a disk. One that is there but cannot be read says
        # nothing - not counted as safe.
        path = os.path.join(block, "backing_dev")
        if not os.path.lexists(path):
            return True
        backing = _read(path, 4096)
        return backing is not None and backing.strip() in ("", "none")
    uuid = (_read(os.path.join(block, "dm", "uuid"), 4096) or "").strip()
    if uuid.startswith("CRYPT-"):
        return True
    try:
        parts = sorted(os.listdir(os.path.join(block, "slaves")))
    except OSError:
        return False
    return bool(parts) and all(encrypted_block(p, sys_root, depth + 1) for p in parts)


def swap_safe(swaps: str | None = None, sys_root: str = SYS) -> tuple[bool, str]:
    """Whether what the system swaps out can be read from a disk afterwards:
    (True, why) when there is no swap or every area is encrypted or in
    memory; (False, why) otherwise - why in a few words for the log."""
    if swaps is None:
        swaps = _read(SWAPS)
        if swaps is None:
            return False, "the system's swap could not be asked"
    areas = swap_list(swaps)
    if not areas:
        return True, "no swap"
    plain = [p for p, kind in areas
             if not encrypted_block(_block_of(p, kind, sys_root) or "", sys_root)]
    if plain:
        return False, "swap not encrypted (" + ", ".join(os.path.basename(p) for p in plain) + ")"
    return True, "swap encrypted"


def stays_in_memory(path: Path | str, mounts: str | None = None, swaps: str | None = None,
                    sys_root: str = SYS) -> tuple[bool, str]:
    """Whether what is written under *path* stays in memory and never
    reaches a disk: (True or False, why)."""
    _point, kind, opts = mount_of(path, mounts)
    if kind not in IN_MEMORY:
        return False, "not in memory"
    if kind == "ramfs" or "noswap" in opts:
        return True, "never swapped"
    return swap_safe(swaps, sys_root)

def private_folder(name: str, mounts: str | None = None, swaps: str | None = None,
                   env: dict | None = None, platform: str | None = None) -> Path | None:
    """The folder for private viewing's *name* files (made, checked): in
    memory, this user's own, out of reach of a disk (stays_in_memory) - or
    None, and why said once in the log."""
    base = private_base(name, env, mounts, platform)
    if base is None:
        why = "no folder of this user's own in memory"
    else:
        try:
            base.mkdir(parents=True, exist_ok=True, mode=0o700)
        except OSError as e:
            why = f"its folder could not be made ({e.strerror or e})"
        else:
            if not own_folder(base):
                why = "its folder is not this user's own"
            else:
                ok, why = stays_in_memory(base, mounts, swaps)
                if ok:
                    return base
    key = (name, why)
    if key not in _SAID:
        _SAID.add(key)
        log.info("private viewing: nothing of it kept for %s - %s", name, why)
    return None

class NoPrivateBuffer(RuntimeError):
    """A channel watched privately gets no rewind buffer: none in memory
    out of a disk's reach (core/memory_safe), and never one on a disk."""

def private_reopen_needed(self) -> bool:
    """Private viewing was turned on while a stream plays whose rewind
    buffer is on the disk - the app's (core/dvr_pool.on_disk_private)
    or mpv's own disk cache: it must be opened again, so what follows
    is kept in memory or not at all."""
    pool = self._dvr_pool
    if self._dvr is not None and pool is not None and pool.on_disk_private():
        return True
    return bool(getattr(self, "_mpv_cache_on_disk", False))

def folder_bytes(folder: str | None) -> int:
    """What the files under *folder* take - a converter's work."""
    total = 0
    for root, _dirs, files in os.walk(folder or ""):
        for name in files:
            try:
                total += os.lstat(os.path.join(root, name)).st_size
            except OSError:
                pass
    return total

def site_headers(url: str = SITE) -> dict:
    """A request's headers: the user agent, and to dopeiptv.org which kind
    of build asks (core/build_check.py) - the site serves no modified one."""
    out = {"User-Agent": user_agent()}
    if is_site(url):
        out.update(build_check.headers())
    return out

def headers() -> dict[str, str]:
    """What every request to dopeiptv.org carries."""
    return {HEADER: kind()}

def kind() -> str:
    return verdict().kind


def allowed() -> bool:
    """dopeiptv.org's services: on, unless this is a modified build."""
    return kind() != MODIFIED

def why_not(sums: bytes, sig: bytes, keys: tuple[str, ...] = KEYS) -> str:
    """"" when *sums* is signed by one of *keys* and well formed, else why not."""
    if not sums.strip():
        return "the release has no SHA256SUMS"
    try:
        raw = base64.b64decode(sig.strip(), validate=True)
    except (binascii.Error, ValueError):
        return "SHA256SUMS.sig is not base64"
    if not any(ed25519.verify(base64.b64decode(k), sums, raw) for k in keys):
        return "SHA256SUMS is not signed with dopeIPTV's release key"
    try:
        lines = sums.decode("utf-8").splitlines()
    except UnicodeDecodeError:
        return "SHA256SUMS is not text"
    bad = [ln for ln in lines if ln and not _LINE.fullmatch(ln)]
    if bad:
        return f"SHA256SUMS has a line that is not a checksum and a file name: {bad[0][:80]!r}"
    return ""

class MonthKeys:
    """The keys every mark of a visitor is made with: one per month, random,
    in this service's memory alone - never in a file on a disk, so never in
    a backup or a copy of one, and gone when the service stops. With
    STATS_KEYS_DIR naming a folder on a file system kept in memory (tmpfs)
    they wait there through a restart too; anywhere else that folder is not
    used. A month's key is kept for KEPT_MONTHS months, then forgotten -
    and with it any way from what is kept back to an address. A line of an
    older month gets a key for this run alone."""

    def __init__(self, today: date, folder: str = "", keys: dict | None = None) -> None:
        self.folder = folder if folder and os.path.isdir(folder) and in_memory(folder) else ""
        got = keys if keys is not None else self._read()
        self.keys: dict = {m: bytes.fromhex(k) for m, k in got.items()
                           if isinstance(k, str) and re.fullmatch(r"[0-9a-f]{64}", k)}
        self._passing: dict = {}
        self.roll(today)

    def _read(self) -> dict:
        if not self.folder:
            return {}
        return _load(os.path.join(self.folder, "keys.json"), {})

    def _write(self) -> None:
        if not self.folder:
            return
        with contextlib.suppress(OSError):
            _save(os.path.join(self.folder, "keys.json"), {m: k.hex() for m, k in self.keys.items()})

    def roll(self, today: date) -> None:
        """Today's months kept, the older keys forgotten."""
        self.month = today.strftime("%Y-%m")
        self.kept = tuple(_months_back(self.month, KEPT_MONTHS))
        gone = [m for m in self.keys if m not in self.kept]
        for m in gone:
            del self.keys[m]
        if gone:
            self._write()

    def key(self, month: str) -> bytes:
        if month in self.keys:
            return self.keys[month]
        if month in self.kept:
            self.keys[month] = secrets.token_bytes(32)
            self._write()
            return self.keys[month]
        return self._passing.setdefault(month, secrets.token_bytes(32))

    def known(self, month: str) -> bytes | None:
        """The month's key if one is kept - never one made for the asking."""
        return self.keys.get(month)

    def kid(self, month: str) -> str:
        """A name for the month's key: which kept marks it can open."""
        return hmac.new(self.key(month), b"id", hashlib.sha256).hexdigest()[:8]

def at_rest(v: dict, day: str, state: dict) -> dict:
    """A visit as it is written down. Its visitor named for this day alone
    (day_id: no two days of one visitor alike) beside the mark sealed
    (seal: nothing to anyone without the month's key, which is in memory
    alone), its start to the half hour and what happened in it to ten
    seconds from there, a screen by its kind, the browser's language without
    its country, a link's site and tag as site_of and source_of keep them -
    and nothing else: no address, no page that linked, no exact time, no
    mark of the device."""
    vid = v.get("id") or ""
    if "did" not in v:
        v["did"] = day_id(state, day, vid) if vid and not v.get("_lost") else vid
    if "w" not in v and vid and not v.get("_lost"):
        v["w"], v["e"] = seal(state, day, vid)
    try:
        start = int(v.get("start") or 0)
    except (TypeError, ValueError):
        start = 0
    s0 = start - start % COARSE

    def t(x) -> int:
        try:
            x = int(x)
        except (TypeError, ValueError):
            return s0
        return s0 + max(0, int(round((x - start) / STEP)) * STEP)

    def secs(x) -> int:
        try:
            return max(0, int(round(int(x) / STEP)) * STEP)
        except (TypeError, ValueError):
            return 0
    out = {"id": v["did"], "start": s0, "end": t(v.get("end", start)),
           "browser": v.get("browser") or "Other", "bv": str(v.get("bv") or "")[:4],
           "os": _plain_os(v.get("os") or ""), "device": v.get("device") or "",
           "country": v.get("country") or "",
           "returning": _small(v.get("returning"), 5),
           "pages": [[t(p[0]), p[1], secs(p[2])] for p in v.get("pages") or ()
                     if isinstance(p, list) and len(p) >= 3],
           "time": secs(v.get("time") or 0),
           "downloads": [[t(d[0]), d[1]] for d in v.get("downloads") or () if isinstance(d, list) and len(d) >= 2],
           "events": [[t(e[0]), *e[1:]] for e in v.get("events") or () if isinstance(e, list) and e]}
    if v.get("acts"):
        out["acts"] = [[t(a[0]), *a[1:]] for a in v["acts"] if isinstance(a, list) and a]
    for k in ("channel", "lang", "hl", "acted", "kind", "why", "w", "e"):
        if k in v:
            out[k] = v[k]
    if "channel" in v:
        out["ref"] = site_of(v.get("ref") or "")[:80]
        out["source"] = source_of(v.get("source") or "")
        out["blang"] = _base_lang(v.get("blang") or "")
        out["screen"] = _screen_kind(v.get("screen") or "")
    return out

def swap_state(now: float | None = None) -> dict:
    """Whether what this service keeps in memory - the month keys, the
    sketches, a folder in memory (STATS_KEYS_DIR) - could reach a disk
    through the system's swap: {"state": ..., "plain": [devices]}.
    "none": no swap. "encrypted": every swap device keeps nothing readable
    once the computer restarts (FreeBSD's .eli with a one-time key, Linux's
    dm-crypt or zram). "plain": a swap device that keeps what it is given -
    said on the admin page and in the log (the server's runbook: encrypted swap).
    "unknown": the system could not be asked."""
    now = time.time() if now is None else now
    if _SWAP and now - _SWAP.get("at", 0) < SWAP_TTL:
        return dict(_SWAP["answer"])
    devices = _swap_devices()
    if devices is None:
        answer: dict = {"state": "unknown", "plain": []}
    elif not devices:
        answer = {"state": "none", "plain": []}
    else:
        plain = [d for d in devices if not (d.endswith(".eli") or _linux_encrypted(d))]
        answer = {"state": "plain" if plain else "encrypted", "plain": plain}
    _SWAP.clear()
    _SWAP.update(at=now, answer=answer)
    return dict(answer)

#: Lines dropped uncounted because swap kept what it was given (swap_state).
SWAP_HELD = {"lines": 0, "said": False}


def _swap_holds() -> bool:
    """Swap that keeps what it is given ("plain"): the run stops before a
    month key is made or read, or a line - each an address - is looked at;
    the lines waiting are dropped, uncounted, and said as a number. Swap
    that could not be asked ("unknown") is warned about on the admin page,
    as before - a jail that cannot ask its host would otherwise count
    nothing ever."""
    return swap_state()["state"] == "plain"

def spots(mark: str) -> tuple:
    """The two bits a mark sets: from its own hex (stats_collect's marks are
    HMAC-SHA256 cut short), else from a hash of it."""
    h = mark if HEX.fullmatch(mark or "") else hashlib.sha256((mark or "").encode()).hexdigest()
    return int(h[0:6], 16) % BITS, int(h[6:12], 16) % BITS


def add(field: int, mark: str) -> int:
    a, b = spots(mark)
    return field | (1 << a) | (1 << b)


def has(field: int, mark: str) -> bool:
    a, b = spots(mark)
    return bool((field >> a) & 1 and (field >> b) & 1)

def count(field: int) -> int:
    """How many different marks set the field (two bits each), estimated as
    a Bloom filter's: -(m/2) ln(1 - set/m)."""
    on = bin(field).count("1")
    if not on:
        return 0
    if on >= BITS:
        return BITS
    return int(round(-(BITS / 2) * math.log(1 - on / BITS)))

def funnel_of(visits: list) -> dict:
    """A day's visits as counts per way in ({channel: FUNNEL}) - what the
    admin page's "by way in" reads of a day whose visits are gone. Likely
    robots left out, as everywhere."""
    out: dict = {}
    for v in visits:
        if not isinstance(v, dict) or not v.get("pages") or v.get("kind") == "robot":
            continue
        secs = v.get("time") or 0
        _funnel_add(out, v.get("channel") or "", len(v["pages"]), secs, secs > 0,
                    bool(v.get("downloads")),
                    any(isinstance(e, list) and e[1:2] == ["donate"] for e in v.get("events") or ()))
    return out

def freeze_months(sketches: dict, frozen: dict, today: date) -> int:
    """The months before the one before this: counted into *frozen* -
    {"days", "unique", "weeks", "judged", "people", "robots"}, as the admin
    page counts them from the sketches - and their sketches deleted. A month
    counted before keeps its numbers. Returns how many months went."""
    keep_from = _month_before(today.strftime("%Y-%m"))
    months = sorted({d[:7] for d in sketches if d[:7] < keep_from})
    for m in months:
        days = sorted(d for d in sketches if d[:7] == m)
        if m not in frozen:
            entries = {d: sketches[d] if isinstance(sketches[d], dict) else {} for d in days}
            weeks: dict = {}
            for d in days:
                weeks[week_of(d)] = weeks.get(week_of(d), 0) | _net_field(entries[d])
            judged = [d for d in days if "p" in entries[d]]
            seen = sketch.union(_net_field(entries[d]) for d in days)
            all_judged = sketch.union(sketch.decode(entries[d].get("u")) for d in judged)
            net_judged = sketch.union(_net_field(entries[d]) for d in judged)
            frozen[m] = {"days": [d for d in days if "u" in entries[d]], "unique": sketch.count(seen),
                         "weeks": {w: sketch.count(f) for w, f in sorted(weeks.items())},
                         "judged": judged,
                         "people": sketch.count(sketch.union(sketch.decode(entries[d].get("p")) for d in judged)),
                         "robots": max(0, sketch.count(all_judged) - sketch.count(net_judged))}
        for d in days:
            sketches.pop(d, None)
    return len(months)


#: The lists of a day that tell who visited (countries, languages, versions,
#: sites, tags): kept with no name fewer than K_DAY once the day's visits are
#: gone - the rest is "other" (fold_day).
FOLD = ("countries", "langs", "os_versions", "browser_versions", "refs", "sources")


def fold_day(stats: dict, day: str) -> None:
    """A day's lists in FOLD, kept for good: the likely robots' part taken
    out first (as the admin page takes it), then a name counted fewer than
    K_DAY times - fewer than five different visitors brought it that day -
    said as "other". It is never added up with other days under its name:
    one person on five days is not five people. A quiet day's few visitors
    are then no longer a country, a language and a browser version side by
    side. Once."""
    d = stats["days"].get(day)
    if not isinstance(d, dict) or d.get("folded"):
        return
    robot_lists = (d.get("robots") or {}).get("lists") or {}
    for k in FOLD:
        if k not in d and k not in robot_lists:
            continue
        lst = dict(d.get(k) or {})
        for name, n in (robot_lists.pop(k, None) or {}).items():
            if lst.get(name, 0) > n:
                lst[name] -= n
            else:
                lst.pop(name, None)
        kept: dict = {}
        moved = 0
        for name, n in lst.items():
            if name == "other" or n >= K_DAY:
                kept[name] = n
            else:
                moved += n
        if moved:
            kept["other"] = kept.get("other", 0) + moved
        d[k] = kept
    d["folded"] = 1


def _forget_old(stats: dict | None = None) -> None:
    """Visits of STATS_VISITS_DAYS days ago and older: their day's counts
    per way in kept (funnel_of), then the day's file deleted - no row of a
    visit stays. Today and the 6 days before it are the 7 kept, so a
    visit is gone 7 days after its day began, at the first run then. The
    day's lists of who came are folded with it (fold_day)."""
    cutoff = (datetime.now(timezone.utc).date() - timedelta(days=VISITS_DAYS)).isoformat()
    for f in sorted(glob.glob(os.path.join(VISITS_DIR, "*.json"))):
        day = os.path.basename(f)[:10]
        if day > cutoff:
            continue
        if stats is not None and day in (stats.get("days") or {}):
            stats["days"][day]["funnel"] = funnel_of(_load_list(f))
        _gone(f)
    if stats is not None:
        for day in sorted(stats.get("days") or {}):
            if day <= cutoff:
                fold_day(stats, day)
    # The app's updates of then: counted in stats.json already, so they go.
    gone_updates = (datetime.now(timezone.utc).date() - timedelta(days=UPDATES_DAYS)).isoformat()
    for f in glob.glob(os.path.join(UPDATES_DIR, "*.json")):
        if os.path.basename(f)[:10] <= gone_updates:
            _gone(f)

def _gone(path: str) -> bool:
    """*path* deleted - or, where that fails, noted in TROUBLE, said once
    in the log and tried again on the next run (sweep_left). A file that is
    not there is gone."""
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass
    except OSError as e:
        if path not in TROUBLE:
            print(f"[stats] could not delete {path} ({e.strerror or type(e).__name__}) - "
                  "tried again on every run until it is gone", flush=True)
        TROUBLE[path] = e.strerror or type(e).__name__
        return False
    TROUBLE.pop(path, None)
    return True

def sweep_left(today: date | None = None) -> list:
    """What left_behind finds deleted once more; what still stays is
    returned (and in TROUBLE). What is no longer there is forgotten."""
    for path in list(TROUBLE):
        if not os.path.lexists(path):
            TROUBLE.pop(path, None)
    stays = [p for p in left_behind(today) if not _gone(p)]
    _gone_folder(ANON_DIR)
    return stays
